"""Composer: builds pattern data for the tune."""
import json

BPM = 150
SPEED = 6
RPB = 16          # rows per bar
BAR = RPB
VAL = lambda midi: midi - 11      # XM note value used by this tracker build
OFF = 97
LOOPROWS = 64     # 4 bars per pattern

# instruments (1-based)
KICK, SNARE, HAT, OPEN, TOM, CLAP, BASS, SUB, CHIP, CHIP2, LEAD, LEAD2, PAD, STAB, RISER, HARP = range(1, 17)
SUSTAINED = {SUB, LEAD, LEAD2, PAD}

# chording helpers
def ch(name):
    return CHORDS[name]
CHORDS = {
 'Am': (45, [0, 4, 7, 12, 16, 19]),      # A2  A C E
 'F' : (41, [0, 4, 7, 12, 16, 19]),      # F2  F A C
 'G' : (43, [0, 4, 7, 12, 14, 17]),      # G2  G B D
 'C' : (48, [0, 4, 7, 12, 16, 19]),      # C3  C E G
 'Dm': (50, [0, 3, 7, 12, 15, 19]),      # D3  D F A
 'Em': (52, [0, 3, 7, 12, 15, 19]),      # E3  E G B
 'E' : (52, [0, 4, 7, 12, 16, 19]),      # E3  E G# B (dominant)
 'G7': (43, [0, 4, 7, 10, 14, 17]),
}

class Pat:
    def __init__(self, rows=64, chcount=12):
        self.rows = rows
        self.cells = {}      # (row,ch) -> dict
    def at(self, row, c, **kw):
        if row >= self.rows: return
        d = self.cells.setdefault((row % self.rows, c), {})
        d.update(kw)
    def note(self, row, c, midi, dur, inst, vel=64, off=True, eff=None, par=None):
        """place a note; sustained instruments get a note-off unless off=False"""
        kw = {'note': VAL(midi), 'instrument': inst, 'volume': max(17, min(64, vel))}
        if eff is not None:
            kw['effect'] = eff; kw['effect_param'] = par
        self.at(row, c, **kw)
        if off and inst in SUSTAINED:
            self.at(row + dur, c, note=OFF)
    def span(self, row, c, inst, vel, eff=None, par=None):
        """non-note cell (e.g. effect only)"""
        kw = {'instrument': inst, 'volume': max(17, min(64, vel))}
        if eff is not None:
            kw['effect'] = eff; kw['effect_param'] = par
        self.at(row, c, **kw)

# ------------------------------------------------------------------ rhythm
def drums(p, style='rock', bars=(0,1,2,3), accent_bar_end=True):
    for b in bars:
        o = b*BAR
        if style == 'none':
            continue
        if style in ('rock','drive','full'):
            p.at(o+0, 0, note=VAL(45), instrument=KICK, volume=64)
            p.at(o+8, 0, note=VAL(45), instrument=KICK, volume=60)
            if style == 'drive' or style == 'full':
                p.at(o+11, 0, note=VAL(45), instrument=KICK, volume=44)
            p.at(o+4, 1, note=VAL(57), instrument=SNARE, volume=58)
            p.at(o+12, 1, note=VAL(57), instrument=SNARE, volume=64)
            if style == 'full':
                p.at(o+14, 1, note=VAL(57), instrument=SNARE, volume=34)
        # hats 8ths
        for i in range(8):
            v = 46 if i % 2 == 0 else 32
            p.at(o+2*i, 2, note=VAL(69), instrument=HAT, volume=v)
        if style == 'full' and accent_bar_end and b % 2 == 1:
            p.at(o+14, 2, note=VAL(67), instrument=OPEN, volume=30)

def fill(p, row, length=16, from_midi=57, to_midi=69):
    """tom/snare fill ending at row+length"""
    n = 8
    for i in range(n):
        r = row + int(i*length/n)
        inst = TOM if i % 2 == 0 else SNARE
        p.at(r, 3, note=VAL(from_midi + (to_midi-from_midi)*i//n + (i % 2)), instrument=inst,
             volume=int(34 + 30*i/n))

def crash(p, row):
    p.at(row, 1, note=VAL(69), instrument=OPEN, volume=44)

# ------------------------------------------------------------------ bass
def bass_bar(p, bar, root, style='eighth', inst=BASS, lo=None):
    o = bar*BAR
    r = root if lo is None else lo
    if style == 'eighth':
        for i in range(8):
            m = r + (12 if i % 2 == 1 else 0)
            p.at(o+2*i, 4, note=VAL(m), instrument=inst, volume=64 if i % 2 == 0 else 50)
    elif style == 'gallop':
        seq = [0, 0, 12, 0, 0, 12, 0, 12]
        for i, s in enumerate(seq):
            p.at(o+2*i, 4, note=VAL(r+s), instrument=inst, volume=64 if s == 0 else 48)
    elif style == 'sixteenth':
        for i in range(16):
            s = 12 if (i % 4 in (1, 3)) else 0
            if i % 8 == 6: s = 7
            p.at(o+i, 4, note=VAL(r+s), instrument=inst, volume=64 if i % 4 == 0 else 44)
    elif style == 'hold':
        p.note(o, 4, r, 16, inst, vel=56)
    elif style == 'off':
        for i in range(4):
            p.at(o+2+4*i, 4, note=VAL(r+12), instrument=inst, volume=48)

# ------------------------------------------------------------------ arps
def arp_seq(root, ints, lo=12, hi=36, steps=16, shape='updown'):
    """build a 16-step sequence of midi notes from chord intervals"""
    tones = [root+lo+i for i in ints] + [root+hi+i for i in ints]
    up = []
    for octv in (0, 12, 24, 36):
        up += [t+octv for t in tones if root+lo <= t+octv <= root+hi+12]
    seq = up + up[-2:0:-1] if shape == 'updown' else up
    out = []
    for i in range(steps):
        out.append(seq[(i*max(1, len(seq)//steps)) % len(seq)])
    return out

def arps(p, chords, rows_per=1, c1=6, c2=7, lo=12, hi=24, vel=42, vel2=34, transpose=0):
    """16th chip arpeggios for each bar"""
    for b, cname in enumerate(chords):
        root, ints = ch(cname)
        seq = arp_seq(root+transpose, ints, lo=lo, hi=hi, steps=16*rows_per)
        o = b*BAR
        for i in range(16):
            n = seq[i*rows_per]
            p.at(o+i, c1, note=VAL(n), instrument=CHIP, volume=vel if i % 4 == 0 else max(24, vel-10))
            p.at(o+i, c2, note=VAL(n-12 if (i % 2) else n-12-5), instrument=CHIP2,
                 volume=vel2 if i % 4 == 0 else max(22, vel2-8))
